// ── Animated Photo Frame ───────────────────────────────────────────────────
function PhotoFrame({ photo, dark }) {
  const [hov, setHov] = useState(false);
  return (
    <div
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      style={{ position:"relative", width:320, height:320, display:"flex", alignItems:"center", justifyContent:"center" }}
    >
      {/* Outer Spinning Gradient Glow Border */}
      <div style={{
        position:"absolute", inset:-6, borderRadius:"50%", padding:3,
        background:"linear-gradient(135deg,#7C3AED,#EC4899,#3B82F6,#7C3AED)",
        backgroundSize:"300% 300%",
        animation:"gradientSpin 5s linear infinite",
        zIndex:0, filter: hov ? "drop-shadow(0 0 20px rgba(124,58,237,0.6))" : "drop-shadow(0 0 10px rgba(124,58,237,0.3))",
        transition:"filter 0.4s ease"
      }}>
        <div style={{
          width:"100%", height:"100%", borderRadius:"50%",
          background: dark ? "#060612" : "#faf7ff"
        }} />
      </div>

      {/* Tech Dashed Orbit Ring */}
      <div style={{
        position:"absolute", inset:-18, borderRadius:"50%",
        border:`2px dashed ${dark ? "rgba(139,92,246,0.35)" : "rgba(139,92,246,0.4)"}`,
        animation:"reverseSpin 15s linear infinite",
        pointerEvents:"none", zIndex:0
      }} />

      {/* Ambient Glow behind photo */}
      <div style={{
        position:"absolute", inset:0, borderRadius:"50%",
        boxShadow: hov
          ? "0 30px 70px rgba(124,58,237,0.4), 0 15px 35px rgba(236,72,153,0.3)"
          : "0 15px 40px rgba(124,58,237,0.18)",
        transition:"box-shadow 0.4s ease", zIndex:-1
      }} />

      {/* Photo Container */}
      <div style={{
        position:"relative", width:"100%", height:"100%",
        borderRadius:"50%", overflow:"hidden", zIndex:1,
        display:"flex", alignItems:"center", justifyContent:"center",
        transform: hov ? "scale(1.04)" : "scale(1)",
        transition:"transform 0.4s ease"
      }}>
        <img
          src={photo}
          alt="wiewien Tancaniago"
          style={{
            width:"100%", height:"100%",
            objectFit:"cover", objectPosition:"center center",
            borderRadius:"50%"
          }}
        />
      </div>

      {/* Name badge */}
      <div style={{
        position:"absolute", bottom:-18, left:"50%", transform:`translateX(-50%) ${hov?"translateY(-4px)":"translateY(0)"}`,
        background: dark ? "rgba(20,10,40,0.92)" : "rgba(255,255,255,0.96)",
        backdropFilter:"blur(14px)",
        border:"1px solid rgba(139,92,246,0.3)",
        borderRadius:22, padding:"8px 22px", zIndex:4,
        boxShadow:"0 10px 30px rgba(139,92,246,0.2)",
        transition:"transform 0.3s ease", whiteSpace:"nowrap"
      }}>
        <span style={{ fontFamily:"'Syne',sans-serif", fontSize:13.5, fontWeight:700, color: dark?"#fff":"#1a0a3a" }}>wiewien Tancaniago</span>
      </div>

      <style>{`
        @keyframes gradientSpin { 0%{background-position:0% 50%} 50%{background-position:100% 50%} 100%{background-position:0% 50%} }
        @keyframes reverseSpin { 0%{transform:rotate(0deg)} 100%{transform:rotate(-360deg)} }
        @keyframes floatBadge1 { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-8px)} }
        @keyframes floatBadge2 { 0%,100%{transform:translateY(0)} 50%{transform:translateY(8px)} }
      `}</style>
    </div>
  );
}

