// ── Skill Card with real logo ───────────────────────────────────────────────
function SkillCard({ item, color, dark }) {
  const [hov, setHov] = useState(false);
  const [imgErr, setImgErr] = useState(false);

  return (
    <div
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      style={{
        display:"flex", flexDirection:"column", alignItems:"center", gap:8, padding:"16px 12px",
        background: hov ? color+"15" : (dark?"rgba(255,255,255,0.025)":"rgba(255,255,255,0.8)"),
        border:`1px solid ${hov ? color+"50" : (dark?"rgba(255,255,255,0.06)":"rgba(139,92,246,0.1)")}`,
        borderRadius:16, transition:"all 0.22s ease", cursor:"default",
        transform: hov ? "translateY(-4px) scale(1.04)" : "none",
        boxShadow: hov ? `0 10px 28px ${color}22` : (dark?"none":"0 2px 12px rgba(139,92,246,0.05)")
      }}
    >
      {!imgErr ? (
        <img
          src={item.icon}
          alt={item.name}
          onError={() => setImgErr(true)}
          style={{ width:38, height:38, objectFit:"contain", filter: dark && item.name==="GitHub" ? "invert(1)" : "none" }}
        />
      ) : (
        /* Fallback: colored initial letter — never emoji */
        <div style={{ width:38, height:38, borderRadius:10, background:`linear-gradient(135deg,${color},${color}88)`, display:"flex", alignItems:"center", justifyContent:"center" }}>
          <span style={{ fontFamily:"'Syne',sans-serif", fontWeight:800, fontSize:16, color:"#fff" }}>{item.name[0]}</span>
        </div>
      )}
      <span style={{ fontFamily:"'DM Sans',sans-serif", fontSize:11, fontWeight:500, color: hov ? color : (dark?"rgba(255,255,255,0.62)":"rgba(30,10,60,0.62)"), textAlign:"center", lineHeight:1.3, transition:"color 0.2s" }}>{item.name}</span>
    </div>
  );
}

