// ── Root ───────────────────────────────────────────────────────────────────
export default function App() {
  const [showIntro, setShowIntro] = useState(true);
  const [active, setActive] = useState("home");
  const [dark, setDark] = useState(false); // default: light/white

  // Only show intro once per session
  useEffect(() => {
    if (typeof sessionStorage !== "undefined" && sessionStorage.getItem("introSeen")) {
      setShowIntro(false);
    }
  }, []);

  function handleIntroDone() {
    if (typeof sessionStorage !== "undefined") sessionStorage.setItem("introSeen","1");
    setShowIntro(false);
  }

  // Active section tracking
  useEffect(() => {
    const sections = ["home","about","projects","experience","certifications","skills","contact"];
    const obs = new IntersectionObserver(entries => entries.forEach(e => { if (e.isIntersecting) setActive(e.target.id); }), { threshold:0.3 });
    sections.forEach(id => { const el = document.getElementById(id); if (el) obs.observe(el); });
    return () => obs.disconnect();
  }, [showIntro]);

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:wght@300;400;500;600&family=DM+Mono:wght@400;500&display=swap');
        *{box-sizing:border-box;margin:0;padding:0}
        html{scroll-behavior:smooth}
        ::-webkit-scrollbar{width:3px}
        ::-webkit-scrollbar-thumb{background:#8B5CF6;border-radius:2px}
        @keyframes blink{0%,100%{opacity:1}50%{opacity:0}}
        @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}

        /* Full Responsive Design for Mobile, Tablet, and Desktop */
        @media (max-width: 992px) {
          .hero-grid {
            grid-template-columns: 1fr !important;
            gap: 2.5rem !important;
            text-align: center !important;
          }
          .hero-text-align {
            display: flex !important;
            flex-direction: column !important;
            align-items: center !important;
          }
          .hero-buttons {
            justify-content: center !important;
          }
          .hero-photo-wrapper {
            margin-top: 0 !important;
          }
          .about-grid {
            grid-template-columns: 1fr !important;
            gap: 2.5rem !important;
          }
        }

        @media (max-width: 768px) {
          nav .nav-container {
            padding: 0 0.75rem !important;
          }
          nav .nav-links-wrap {
            overflow-x: auto !important;
            white-space: nowrap !important;
            max-width: 55vw !important;
            padding-bottom: 2px;
            -webkit-overflow-scrolling: touch;
          }
          nav .nav-links-wrap::-webkit-scrollbar {
            display: none !important;
          }
          section {
            padding-left: 1.2rem !important;
            padding-right: 1.2rem !important;
            padding-top: 80px !important;
            padding-bottom: 60px !important;
          }
          .cert-grid, .projects-grid {
            grid-template-columns: 1fr !important;
          }
        }
      `}</style>

      {showIntro && <IntroScreen onDone={handleIntroDone} />}

      <div style={{ background: dark ? "#060612" : "#faf7ff", minHeight:"100vh" }}>
        <Nav active={active} dark={dark} setDark={setDark} />
        <Hero dark={dark} />
        <About dark={dark} />
        <Projects dark={dark} />
        <Experience dark={dark} />
        <Certifications dark={dark} />
        <Skills dark={dark} />
        <Contact dark={dark} />
      </div>
    </>
  );
}
